package com.MITProjectService.bot.domain;import jakarta.persistence.*;import lombok.Data;import java.math.BigDecimal;@Data@Entity@Table(name = "user_payment_account")public class UserPaymentAccount {    @Id    @Column(name = "id")    @GeneratedValue(strategy = GenerationType.IDENTITY)    private Long id;    @JoinColumn(name = "user_id", nullable = false)    @OneToOne(fetch = FetchType.EAGER)    private ServiceProvider serviceProvider;    @Column(name = "amount", nullable = false)    private Double accountBalance;    @Column(name = "currency", nullable = false)    private String currency;    @Column(name = "account_number", nullable = false)    private String accountNumber;    @Column(name = "status", nullable = false)    private Integer status;}